schema:
{
  "title": "Contact",
  "type": "object",
  "properties": {
    "email": {
      "type": "string",
      "format": "email"
    },
    "phone": {
      "type": "string",
      "pattern": "^\\+?[0-9 ()-]{7,20}$"
    },
    "description": {
      "type": "string",
      "maxLength": 500,
      "description": "How we met, in a sentence or two."
    },
    "linkedin": {
      "type": "string",
      "format": "uri"
    }
  },
  "required": ["email", "phone"]
}

